  <main id="main-content">
    <section class="support-shell" aria-labelledby="support-heading">
      <p class="eyebrow">Support</p>
      <h1 id="support-heading">Contact our support team</h1>
      <p class="intro">Share your contact details and we will reach out to help with your request.</p>
      <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">
            Full name
            <span class="required-mark" aria-hidden="true">*</span>
            <span class="sr-only"> required</span>
          </label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
          >
          <p class="field-error" id="full-name-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="email-address">
            Email address
            <span class="required-mark" aria-hidden="true">*</span>
            <span class="sr-only"> required</span>
          </label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            inputmode="email"
            required
          >
          <p class="field-error" id="email-address-error" hidden></p>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number <span class="field-help">(optional)</span></label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-number-help"
          >
          <p class="field-help" id="phone-number-help">Expected format: (555) 123-4567 or +1 555 123 4567.</p>
          <p class="field-error" id="phone-number-error" hidden></p>
        </div>

        <button type="submit">Send support request</button>
        <p class="status-message" id="form-status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const statusMessage = document.getElementById('form-status');

    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        describedBy: '',
        validate(value) {
          if (!value.trim()) {
            return 'Error: Enter your full name.';
          }
          return '';
        }
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        describedBy: '',
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return 'Error: Enter your email address.';
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmedValue)) {
            return 'Error: Enter a valid email address, like name@example.com.';
          }
          return '';
        }
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        describedBy: 'phone-number-help',
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return '';
          }
          const phonePattern = /^\+?[0-9().\-\s]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return 'Error: Enter a phone number in the expected format.';
          }
          return '';
        }
      }
    ];

    function updateDescriptions(field, showError) {
      const describedBy = [];
      if (field.describedBy) {
        describedBy.push(field.describedBy);
      }
      if (showError) {
        describedBy.push(field.error.id);
      }
      if (describedBy.length > 0) {
        field.input.setAttribute('aria-describedby', describedBy.join(' '));
      } else {
        field.input.removeAttribute('aria-describedby');
      }
    }

    function showError(field, message) {
      field.error.textContent = message;
      field.error.hidden = false;
      field.input.setAttribute('aria-invalid', 'true');
      updateDescriptions(field, true);
    }

    function clearError(field) {
      field.error.textContent = '';
      field.error.hidden = true;
      field.input.removeAttribute('aria-invalid');
      updateDescriptions(field, false);
    }

