      <h1 id="support-heading">Contact our support team</h1>
      <p class="intro">Share your contact details and we will reach out to help with your request.</p>
      <p class="required-note"><span aria-hidden="true">*</span> Required fields</p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">
            Full name
            <span class="required-mark" aria-hidden="true">*</span>
            <span class="sr-only"> required</span>
          </label>
          <input
            id="full-name"
            name="fullName"
