          <label for="phone-number">Phone number <span class="field-help">(optional)</span></label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-number-help"
          >
          <p class="field-help" id="phone-number-help">Expected format: (555) 123-4567 or +1 555 123 4567.</p>
          <p class="field-error" id="phone-number-error" hidden></p>
