     const fields = [
       {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         describedBy: '',
         validate(value) {
           if (!value.trim()) {
             return 'Error: Enter your full name.';
           }
           return '';
         }
       },
       {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-address-error'),
         describedBy: '',
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return 'Error: Enter your email address.';
           }
           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(trimmedValue)) {
             return 'Error: Enter a valid email address, like name@example.com.';
           }
           return '';
         }
       },
       {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-number-error'),
         describedBy: 'phone-number-help',
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return '';
           }
           const phonePattern = /^\+?[0-9().\-\s]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             return 'Error: Enter a phone number in the expected format.';
           }
           return '';
         }
       }
     ];

     function updateDescriptions(field, showError) {
       const describedBy = [];
       if (field.describedBy) {
         describedBy.push(field.describedBy);
       }
       if (showError) {
         describedBy.push(field.error.id);
       }
       if (describedBy.length > 0) {
         field.input.setAttribute('aria-describedby', describedBy.join(' '));
       } else {
         field.input.removeAttribute('aria-describedby');
       }
     }

     function showError(field, message) {
       field.error.textContent = message;
       field.error.hidden = false;
       field.input.setAttribute('aria-invalid', 'true');
       updateDescriptions(field, true);
     }

     function clearError(field) {
       field.error.textContent = '';
       field.error.hidden = true;
       field.input.removeAttribute('aria-invalid');
       updateDescriptions(field, false);
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       if (message) {
         showError(field, message);
         return false;
       }
       clearError(field);
       return true;
     }

     fields.forEach((field) => {
       field.input.addEventListener('blur', () => {
         validateField(field);
       });

       field.input.addEventListener('input', () => {
         if (!field.error.hidden) {
           validateField(field);
         }
         statusMessage.textContent = '';
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();
       statusMessage.textContent = '';

       let firstInvalidField = null;

       fields.forEach((field) => {
         const isValid = validateField(field);
         if (!isValid && !firstInvalidField) {
           firstInvalidField = field.input;
         }
       });

       if (firstInvalidField) {
         firstInvalidField.focus();
         return;
       }

       statusMessage.textContent = 'Thanks. Your support request is ready to send.';
       form.reset();
       fields.forEach(clearError);
       document.getElementById('phone-number').setAttribute('aria-describedby', 'phone-number-help');
     });
   </script>
 </body>
 </html>

